def factorial(n):
    # Check if n is a non-negative integer
    if type(n) is not int or n < 0:
        return "The input number should be a non-negative integer."

    # Base case
    if n == 0:
        return 1
    # Recursion case
    else:
        return n * factorial(n - 1)

